CREATE TABLE roles(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`name` varchar(255)  NOT NULL)ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;